class Solution {
public:
    int numRollsToTarget(int n, int k, int target) {
        const int MOD = 1000000007;
        vector<int> prev(target + 1, 0), cur(target + 1, 0);
        vector<long long> pref(target + 2, 0);
        prev[0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int s = 0; s <= target; s++)
                pref[s + 1] = (pref[s] + prev[s]) % MOD;
            for (int s = 1; s <= target; s++) {
                int lo = max(0, s - k);
                cur[s] = (int)((pref[s] - pref[lo] + MOD) % MOD);
            }
            swap(prev, cur);
            fill(cur.begin(), cur.end(), 0);
        }
        return prev[target];
    }
};
